const SYSTEM_LIGHT = 'aurora', SYSTEM_DARK = 'midnight';

export function resolveTheme(pref) {
  if (pref !== 'system') return pref;
  return window.matchMedia('(prefers-color-scheme: dark)').matches ? SYSTEM_DARK : SYSTEM_LIGHT;
}

export function applyTheme(pref, { map } = {}) {
  const resolved = resolveTheme(pref);
  document.documentElement.setAttribute('data-theme', resolved);
  document.documentElement.setAttribute('data-theme-pref', pref);
  localStorage.setItem('bf-theme', pref);
  if (map) map.setOptions({ styles: THEMES[resolved].mapStyle });
  return resolved;
}

// Live-follow the OS when the user picked "system" (inline boot script only reads it once).
window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', () => {
  if (localStorage.getItem('bf-theme') === 'system' || !localStorage.getItem('bf-theme')) {
    applyTheme('system', { map: window.__bfMap });
  }
});
