Sheet drag (no library — raw Pointer Events), in public/js/sheet.js:
```js
export function attachSheetDrag(panel, handle) {
  let startY = 0, startState = 'peek';
  const heights = { hidden: '100%', peek: 'calc(100% - 132px)', full: '0%' };
  handle.addEventListener('click', () => {
    const next = panel.dataset.sheet === 'peek' ? 'full' : 'peek';
    panel.dataset.sheet = next;
  });
  handle.addEventListener('pointerdown', (e) => {
    startY = e.clientY; startState = panel.dataset.sheet;
    handle.setPointerCapture(e.pointerId);
    panel.style.transition = 'none';
  });
  handle.addEventListener('pointermove', (e) => {
    if (!e.buttons) return;
    const dy = e.clientY - startY;
    panel.style.transform = `translateY(${Math.max(0, dy)}px)`;
  });
  handle.addEventListener('pointerup', (e) => {
    panel.style.transition = '';
    panel.style.transform = '';
    const dy = e.clientY - startY;
    panel.dataset.sheet = dy > 60 ? 'peek' : dy < -60 ? 'full' : startState;
  });
}
```
