```js
export function pinSvg(color, active) {
  const r = active ? 15 : 11;
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${r*2+6}" height="${r*2+10}" viewBox="0 0 ${r*2+6} ${r*2+10}">
    <path d="M${r+3} ${r*2+8} C${r+3} ${r*2+8} 3 ${r+8} 3 ${r+3} A${r} ${r} 0 1 1 ${r*2+3} ${r+3} C${r*2+3} ${r+8} ${r+3} ${r*2+8} ${r+3} ${r*2+8} Z" fill="${color}" stroke="#fff" stroke-width="2"/>
  </svg>`;
  return 'data:image/svg+xml;charset=UTF-8,' + encodeURIComponent(svg);
}

export function createMapController(el, { center, styles }) {
  const map = new google.maps.Map(el, { center, zoom: 14, styles, disableDefaultUI: true, zoomControl: true, clickableIcons: false });
  const markers = new Map(); // placeId -> google.maps.Marker
  let activeId = null;

  function render(places, accentColor) {
    for (const m of markers.values()) m.setMap(null);
    markers.clear();
    const bounds = new google.maps.LatLngBounds();
    for (const p of places) {
      if (p.lat == null || p.lng == null) continue;
      const marker = new google.maps.Marker({
        position: { lat: p.lat, lng: p.lng }, map,
        icon: { url: pinSvg(accentColor, false), anchor: new google.maps.Point(14, 32) },
        title: p.name,
      });
      marker.addListener('click', () => select(p.id));
      markers.set(p.id, marker);
      bounds.extend(marker.getPosition());
    }
    if (places.length) map.fitBounds(bounds, 48);
  }

  function select(placeId, accentColor) {
    if (activeId && markers.has(activeId)) markers.get(activeId).setIcon({ url: pinSvg(accentColor, false), anchor: new google.maps.Point(14, 32) });
    activeId = placeId;
    const marker = markers.get(placeId);
    if (marker) {
      marker.setIcon({ url: pinSvg(accentColor, true), anchor: new google.maps.Point(18, 40) });
      map.panTo(marker.getPosition());
    }
    return placeId;
  }

  return { map, render, select };
}
```
