  root.append(gallery);

  root.append(el('h2', {}, p.name));
  const meta = el('div', { class:'detail-meta' });
  if (p.rating != null) meta.insertAdjacentHTML('beforeend', starString(p.rating));
  if (p.rating != null) meta.append(el('span', { class:'rating-num' }, `${p.rating.toFixed(1)} (${p.ratingCount ?? 0})`));
  if (p.priceLevel) meta.append(el('span', { class:'price' }, PRICE_LABEL[p.priceLevel] || ''));
  if (p.openNow === true) meta.append(el('span', { class:'badge badge-open' }, 'Open now'));
  else if (p.openNow === false) meta.append(el('span', { class:'badge badge-closed' }, 'Closed'));
  root.append(meta);

  if (p.address) root.append(el('p', { class:'address' }, p.address));

  const actions = el('div', { class:'detail-actions' });
  actions.append(el('a', { class:'btn btn-primary', target:'_blank', rel:'noopener noreferrer',
    href:`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(p.lat + ',' + p.lng)}&destination_place_id=${encodeURIComponent(p.id)}` }, 'Directions'));
  if (p.phone) actions.append(el('a', { class:'btn btn-ghost', href:`tel:${p.phone.replace(/[^0-9+]/g,'')}` }, 'Call'));
  if (/^https?:\/\//i.test(p.website || '')) actions.append(el('a', { class:'btn btn-ghost', target:'_blank', rel:'noopener noreferrer', href:p.website }, 'Website'));
  actions.append(buildSaveButton(p));
  root.append(actions);

  if (p.weekdayHours?.length) {
    const details = el('details', { class:'hours' });
    details.append(el('summary', {}, 'Hours'));
    const ul = el('ul');
    for (const line of p.weekdayHours) ul.append(el('li', {}, line));
    details.append(ul);
    root.append(details);
  }

  root.append(buildReviewsSection(p.reviews));
  return root;
}

function buildReviewsSection(reviews) {
  const section = el('section', { class:'reviews', 'aria-label':'Reviews' });
  section.append(el('h3', {}, 'Reviews'));
  if (!reviews || !reviews.length) {
    section.append(el('p', { class:'muted' }, 'No reviews yet.'));
  } else {
    const list = el('ul', { class:'review-list' });
    for (const r of reviews) list.append(buildReviewCard(r));
    section.append(list);
  }
  // Required attribution block — see risk note about the actual Google-provided asset.
  section.append(el('div', { class:'google-attribution' },
    [el('img', { src:'/assets/google-on-white.png', alt:'Google', height:'18' }), el('span', { class:'muted' }, 'Ratings and reviews from Google')]));
  return section;
}

function buildReviewCard(r) {
  const card = el('li', { class:'review-card' });
  const head = el('div', { class:'review-head' });

  let avatar;
  if (r.authorPhoto) {
    avatar = document.createElement('img');
    avatar.className = 'review-avatar'; avatar.alt = ''; avatar.referrerPolicy = 'no-referrer';
    avatar.src = r.authorPhoto;
    avatar.addEventListener('error', () => avatar.replaceWith(initialsNode(r.author)), { once:true });
  } else {
    avatar = initialsNode(r.author);
  }
  head.append(avatar);

  const who = el('div', { class:'review-who' });
  const safeProfile = /^https?:\/\//i.test(r.profileUri || '') ? r.profileUri : null;
  who.append(safeProfile
    ? el('a', { class:'review-author', href:safeProfile, target:'_blank', rel:'noopener noreferrer' }, r.author)
    : el('span', { class:'review-author' }, r.author));
  const starsWrap = el('span', { class:'review-stars' }); starsWrap.innerHTML = starString(r.rating);
  who.append(starsWrap, el('time', { class:'review-time' }, r.relativeTime));
  head.append(who);

  card.append(head, el('p', { class:'review-text' }, r.text));
  return card;
}

function initialsNode(name) {
  const initials = String(name || '?').trim().split(/\s+/).map((w) => w[0]).slice(0,2).join('').toUpperCase();
  return el('span', { class:'review-avatar review-avatar-fallback' }, initials);
}
```
Every function above builds the review/photo/attribution nodes via `el()`/DOM property assignment (never `innerHTML` + raw interpolation) because `author`, `text`, `authorPhoto`, `profileUri` all come from third parties (Google users) and must never be trusted as markup.

```js
export function requestLocation({ onState, onLocation }) {
  if (!('geolocation' in navigator)) {
    onState({ kind:'unsupported', message:'Location isn't supported in this browser. Enter a city or address to search near.' });
    return;
  }
  if (!window.isSecureContext) {
    onState({ kind:'insecure', message:'Location requires a secure (https) connection here. Enter a city or address to search near.' });
    return;
  }
  onState({ kind:'requesting', message:'Finding your location…' });
  navigator.geolocation.getCurrentPosition(
    (pos) => {
      onState({ kind:'granted' });
      onLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude, source:'gps', label:'your location' });
    },
    (err) => {
      if (err.code === err.PERMISSION_DENIED) {
        onState({ kind:'denied', message:"Location access is off. Enter a city or address to search near, or turn it on in your browser's site settings." });
      } else if (err.code === err.TIMEOUT) {
        onState({ kind:'timeout', message:"That's taking a while. Try again, or enter a location.", retry:true });
      } else {
        onState({ kind:'error', message:"We couldn't determine your location. Enter a place to search near." });
      }
    },
    { enableHighAccuracy:false, timeout:8000, maximumAge:5*60*1000 }
  );
}

export async function searchManualLocation(query, { onState, onLocation }) {
  onState({ kind:'geocoding', message:`Looking up “${query}”…` });
  try {
    const data = await geocodeQuery(query);
    onState({ kind:'manual-set', message:`Showing places near ${data.formattedAddress}.` });
    onLocation({ lat:data.lat, lng:data.lng, source:'manual', label:data.formattedAddress });
  } catch (err) {
    if (err.status === 404) onState({ kind:'manual-error', message:`We couldn't find “${query}”. Try a more specific address or city.` });
    else if (err.status === 429) onState({ kind:'manual-error', message:'Location lookups are busy right now — try again in a minute.' });
    else onState({ kind:'manual-error', message:'Something went wrong looking that up. Try again.' });
  }
}
```
Banner copy per state (rendered in `#location-banner`, `aria-live="polite"` so screen readers announce transitions):
- idle: "Allow location to see what's near you." — [Use my location] [Enter a location]
- requesting: "Finding your location…" (spinner, no buttons)
- granted: banner clears; a small persistent pill "Near you" sits by the locate FAB
- denied: "Location access is off. Enter a city or address to search near, or turn it on in your browser's site settings." + inline text input
- timeout: "That's taking a while. Try again, or enter a location." — [Try again] [Enter a location]
- unsupported / insecure: "Location isn't supported in this browser." / "Location requires a secure (https) connection here." + inline text input, no retry button (retrying can't help)
- manual-set: "Showing places near {formattedAddress}." + [×] clears back to idle and offers GPS again
- manual-error (404): "We couldn't find “{query}”. Try a more specific address or city."
- manual-error (429): "Location lookups are busy right now — try again in a minute."

When `state.user` is set and a location resolves (GPS or manual), fire-and-forget `postLocation(lat,lng)` so friends who the user shares with can see them (server fuzzes to 2dp) — this must never block or fail the search flow, so it's wrapped in `.catch(() => {})` and not awaited.

