```js
function haversineMeters(a, b) {
  const R = 6371000, toRad = (d) => d * Math.PI / 180;
  const dLat = toRad(b.lat - a.lat), dLng = toRad(b.lng - a.lng);
  const s = Math.sin(dLat/2)**2 + Math.cos(toRad(a.lat)) * Math.cos(toRad(b.lat)) * Math.sin(dLng/2)**2;
  return R * 2 * Math.asin(Math.sqrt(s));
}

function applyFilters(results, filters, userLoc) {
  let out = results.filter((p) => (filters.minRating ? (p.rating ?? 0) >= filters.minRating : true));
  if (filters.openNow) out = out.filter((p) => p.openNow === true); // see risk note: field not in Nearby mask today
  out = out.map((p) => ({ ...p, distanceM: userLoc ? haversineMeters(userLoc, p) : null }));
  const sorters = {
    distance: (a, b) => (a.distanceM ?? Infinity) - (b.distanceM ?? Infinity),
    rating: (a, b) => (b.rating ?? 0) - (a.rating ?? 0),
    reviews: (a, b) => (b.ratingCount ?? 0) - (a.ratingCount ?? 0),
  };
  return out.sort(sorters[filters.sort] || sorters.distance);
}
```
Rating/sort/openNow apply client-side, instantly, over the already-fetched result set — no network call. Radius is different: it's a Google `locationRestriction.circle.radius` parameter on the server, so changing it must re-issue `GET /api/nearby?...&radius=` (debounced ~400ms) rather than filtering client-side. The 'Open now' chip is shipped visibly disabled-looking (title tooltip explaining why) until the Nearby field mask carries `regularOpeningHours.openNow` — see risks; the code above is written so it activates for free the moment that field appears in `/api/nearby` responses, no frontend changes needed.

