export function startRouter(mountEl, viewTable) {
  async function run() {
    const hash = location.hash || '#/map';
    const match = routes.find((r) => r.pattern.test(hash));
    if (!match) { location.hash = '#/map'; return; }
    if (match.auth && !state.user) { location.hash = `#/login?redirect=${encodeURIComponent(hash)}`; return; }
    const params = hash.match(match.pattern).slice(1);
    mountEl.dataset.route = match.view;
    await viewTable[match.view](mountEl, ...params);
    mountEl.querySelector('h1')?.focus?.(); // move focus for a11y on route change
  }
  window.addEventListener('hashchange', run);
  run();
